/**
 * Fields for one form file name, or [] when the form has none.
 *
 * Hand-authored entries in formFieldOverrides.js are merged in here: they
 * either REPLACE what the scanner found (table forms, where the scan is
 * noise) or are appended to it. Doing the merge in this one accessor means
 * no screen has to know that two sources exist.
 */
export function getFieldsForFile(fileName) {
    /* A measured, hand-authored layout is complete for its file and wins
     * over scanner output and overrides (src/config/formLayouts). */
    const authored = getAuthoredLayout(fileName);
    if (authored) return normalizeFieldDefinitions({ fields: authored.fields, pageCount: authored.pageCount }).fields;

    const scanned = FORM_FIELDS[fileName]?.fields ?? [];
    const override = FORM_FIELD_OVERRIDES[fileName];

    const fields = !override ? scanned : override.replace ? override.fields : [...scanned, ...override.fields];
    return normalizeFieldDefinitions({ fields, pageCount: FORM_FIELDS[fileName]?.pageCount }).fields;
}
